#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) { ilen = fread(ibuf, 1, sizeof ibuf, stdin); ipos = 0; if (!ilen) return -1; }
    return ibuf[ipos++];
}
static inline long long readInt() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

int main() {
    int t = readInt();
    string out;
    while (t--) {
        int n = readInt(), m = readInt();
        // previous[c] = max K over cell c of the previous row and all its ancestors (padded by 0).
        vector<int> previous(m + 2, 0), current(m + 2, 0);
        for (int r = 0; r < n; r++) {
            for (int c = 1; c <= m; c++) {
                int value = readInt();
                int ancestor = max(previous[c - 1], max(previous[c], previous[c + 1]));
                out += ancestor > value ? '1' : '0';
                out += c == m ? '\n' : ' ';
                current[c] = max(value, ancestor);
            }
            swap(previous, current);
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static int readInt() throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        int x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int t = readInt();
        ByteArrayOutputStream bout = new ByteArrayOutputStream(1 << 20);
        while (t-- > 0) {
            int n = readInt(), m = readInt();
            // previous[c] = max K over cell c of the previous row and all its ancestors (padded by 0).
            int[] previous = new int[m + 2], current = new int[m + 2];
            byte[] line = new byte[2 * m];
            for (int r = 0; r < n; r++) {
                for (int c = 1; c <= m; c++) {
                    int value = readInt();
                    int ancestor = Math.max(previous[c - 1], Math.max(previous[c], previous[c + 1]));
                    line[2 * (c - 1)] = (byte) (ancestor > value ? '1' : '0');
                    line[2 * (c - 1) + 1] = (byte) (c == m ? '\n' : ' ');
                    current[c] = Math.max(value, ancestor);
                }
                bout.write(line, 0, line.length);
                int[] tmp = previous; previous = current; current = tmp;
            }
        }
        System.out.write(bout.toByteArray());
        System.out.flush();
    }
}

package main

import (
	"bufio"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int {
	c, _ := reader.ReadByte()
	for c != '-' && (c < '0' || c > '9') {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	x := 0
	for c >= '0' && c <= '9' {
		x = x*10 + int(c-'0')
		var err error
		c, err = reader.ReadByte()
		if err != nil {
			break
		}
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	writer := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer writer.Flush()
	t := readInt()
	for ; t > 0; t-- {
		n, m := readInt(), readInt()
		// previous[c] = max K over cell c of the previous row and all its ancestors (padded by 0).
		previous := make([]int, m+2)
		current := make([]int, m+2)
		line := make([]byte, 2*m)
		for r := 0; r < n; r++ {
			for c := 1; c <= m; c++ {
				value := readInt()
				ancestor := max(previous[c-1], previous[c], previous[c+1])
				if ancestor > value {
					line[2*(c-1)] = '1'
				} else {
					line[2*(c-1)] = '0'
				}
				if c == m {
					line[2*(c-1)+1] = '\n'
				} else {
					line[2*(c-1)+1] = ' '
				}
				current[c] = max(value, ancestor)
			}
			writer.Write(line)
			previous, current = current, previous
		}
	}
}
